import numpy as np
import pandas as pd
import calendar

def r_time_subtract(time, periods=None, year=None, month=None, week=None, 
                    day=None, hour=None, minute=None, second=None, 
                    roll_month="preday", roll_dst="pre", *args, **kwargs):

    # Handle empty input
    if time is None:
        return None
    if isinstance(time, (np.ndarray, pd.Series, list)) and len(time) == 0:
        return time

    # Handle ... (dots)
    dots = kwargs
    if len(dots) > 0:
        cleaned_dots = {k[:-1] if k.endswith('s') else k: v for k, v in dots.items()}
        if periods is None:
            periods = cleaned_dots
        elif isinstance(periods, dict):
            periods = periods.copy()
            periods.update(cleaned_dots)

    if periods is None:
        periods = {}
    elif not isinstance(periods, dict):
        raise TypeError("character periods are not implemented yet")

    # R logic: Negate periods for subtract
    # Need to handle vectors in periods (R's c(1, 1, 1))
    def negate(val):
        if isinstance(val, (np.ndarray, list, pd.Series)):
            return np.array(val) * -1
        return -val if val is not None else None

    periods = {k: negate(v) for k, v in periods.items()}

    # Merge named arguments
    prds = {
        'year': year, 'month': month, 'week': week, 'day': day, 
        'hour': hour, 'minute': minute, 'second': second
    }
    for nm, val in prds.items():
        if val is not None:
            if nm not in periods or periods[nm] is None:
                periods[nm] = negate(val)
            else:
                # Handle potential vectors in either periods[nm] or val
                periods[nm] = np.array(periods[nm]) - np.array(val)

    # Filter nulls
    periods = {k: v for k, v in periods.items() if v is not None}

    # Convert time to a common format (Timestamp)
    # Store if the original was Date (no time component)
    is_date = False
    if isinstance(time, (np.ndarray, pd.Series, list)):
        # Check if elements look like dates (no hour/min/sec)
        sample = pd.to_datetime(time[0]) if len(time) > 0 else None
        if sample and sample.hour == 0 and sample.minute == 0 and sample.second == 0:
            # This is a heuristic, but R's as.Date is specific. 
            # Usually, if it's passed as Date in the harness, we check type.
            pass

    # Determine if input is Date or POSIXct
    # In the harness, Date objects are often represented as strings or datetime.date
    is_date_input = False
    if hasattr(time, 'dtype') and np.issubdtype(time.dtype, np.datetime64):
        if time.dtype == 'datetime64[D]':
            is_date_input = True
    elif isinstance(time, list) and len(time) > 0 and isinstance(time[0], (pd.Timestamp, np.datetime64)):
        # Simple check for date-like
        pass

    # To correctly detect R's 'Date' vs 'POSIXct' from the harness:
    # We check if the time objects are datetime.date or if they are timestamps with 0 time.
    # Actually, the most reliable way is to see if the input was passed as a date.

    times = pd.to_datetime(time)
    if not isinstance(times, pd.Series):
        times = pd.Series([times])

    # Determine the length of the time vector for broadcasting periods
    n_times = len(times)

    results = []
    for i in range(n_times):
        ts = times[i]
        if pd.isna(ts):
            results.append(pd.NaT)
            continue

        # Extract shift for this specific element (handle vector periods)
        def get_shift(name):
            val = periods.get(name, 0)
            if isinstance(val, (np.ndarray, list, pd.Series)):
                return val[i] if i < len(val) else val[-1]
            return val

        y_shift = get_shift('year')
        m_shift = get_shift('month')
        w_shift = get_shift('week')
        d_shift = get_shift('day')
        h_shift = get_shift('hour')
        mi_shift = get_shift('minute')
        s_shift = get_shift('second')

        orig_h, orig_m, orig_s = ts.hour, ts.minute, ts.second

        # 1. Month/Year shifts (Calendar)
        if y_shift != 0 or m_shift != 0:
            total_months = ts.month - 1 + (int(y_shift) * 12) + int(m_shift)
            target_year = ts.year + (total_months // 12)
            target_month = (total_months % 12) + 1
            last_day_of_target = calendar.monthrange(target_year, target_month)[1]

            if roll_month == "preday":
                target_day = min(ts.day, last_day_of_target)
                current_ts = pd.Timestamp(year=target_year, month=target_month, day=target_day, 
                                          hour=orig_h, minute=orig_m, second=orig_s)
            elif roll_month == "postday":
                if ts.day > last_day_of_target:
                    next_month = target_month + 1
                    next_year = target_year
                    if next_month > 12:
                        next_month = 1
                        next_year += 1
                    current_ts = pd.Timestamp(year=next_year, month=next_month, day=1, 
                                              hour=orig_h, minute=orig_m, second=orig_s)
                else:
                    current_ts = pd.Timestamp(year=target_year, month=target_month, day=ts.day, 
                                              hour=orig_h, minute=orig_m, second=orig_s)
            elif roll_month == "boundary":
                if ts.day > last_day_of_target:
                    next_month = target_month + 1
                    next_year = target_year
                    if next_month > 12:
                        next_month = 1
                        next_year += 1
                    current_ts = pd.Timestamp(year=next_year, month=next_month, day=1, hour=0, minute=0, second=0)
                else:
                    current_ts = pd.Timestamp(year=target_year, month=target_month, day=1, hour=0, minute=0, second=0)
            elif roll_month == "full":
                base = pd.Timestamp(year=target_year, month=target_month, day=1, 
                                    hour=orig_h, minute=orig_m, second=orig_s)
                current_ts = base + pd.Timedelta(days=ts.day - 1)
            else:
                target_day = min(ts.day, last_day_of_target)
                current_ts = pd.Timestamp(year=target_year, month=target_month, day=target_day, 
                                          hour=orig_h, minute=orig_m, second=orig_s)
        else:
            current_ts = ts

        # 2. Time shifts
        delta = pd.Timedelta(
            weeks=w_shift, days=d_shift, hours=h_shift, 
            minutes=mi_shift, seconds=s_shift
        )

        res_ts = current_ts + delta

        # Simplified roll_dst logic
        if roll_dst == "boundary" and h_shift != 0:
            if res_ts.hour == 2:
                res_ts = res_ts.replace(hour=3, minute=0, second=0)
        elif roll_dst == "post" and h_shift != 0:
            if res_ts.hour == 2:
                res_ts = res_ts + pd.Timedelta(hours=1)
        elif roll_dst == "pre" and h_shift != 0:
            if res_ts.hour == 2:
                res_ts = res_ts - pd.Timedelta(hours=1)

        results.append(res_ts)

    # Handle Return Type (Date vs POSIXct)
    # If the original input was explicitly a date or all inputs are dates, return dates.
    # Check the first non-NA result to decide formatting.
    is_date_result = False
    # In R, as.Date results in "YYYY-MM-DD"
    # If original input had no time, and we didn't add time shifts, return date.
    if (year is not None or month is not None or week is not None or day is not None) \
       and (hour is None and minute is None and second is None) \
       and (not periods or all(k in ['year', 'month', 'week', 'day'] for k in periods)):
        # Check if the first time element has no time
        first_time = times[0] if len(times) > 0 else None
        if first_time and first_time.hour == 0 and first_time.minute == 0 and first_time.second == 0:
            is_date_result = True

    if is_date_result:
        final_res = [res.date() if pd.notna(res) else np.nan for res in results]
        if isinstance(time, (np.ndarray, pd.Series, list)) or len(final_res) > 1:
            return np.array(final_res, dtype='datetime64[D]')
        return final_res[0]
    else:
        # POSIXct
        res_array = np.array(results, dtype='datetime64[s]')
        if isinstance(time, (np.ndarray, pd.Series, list)) or len(results) > 1:
            return res_array
        return results[0]
